        shayariItem(1324, "मोटू बोला 'मुझे गुस्सा बहुत कम आता है पतलू,'\nबस कोई मेरी थाली से समोसा न उठा ले पतलू!", "फुरफुरी नगर स्पेशल", catMotuPatlu, "थाली"),
        shayariItem(1325, "पतलू की पतली कमर और मोटू का बड़ा दिल,\nइन दोनों के सामने हर विलेन की हो जाती हालत ढिल।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "दिल"),
        shayariItem(1326, "पिकनिक पर भी मोटू टिफ़िन सबसे पहले खोलता है,\nबाक़ी सब देखते रह जाते हैं और ये 'बहुत टेस्टी है' बोलता है।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "पिकनिक"),
        shayariItem(1327, "ज़िंदगी में हमेशा ऐसे दोस्त बनाओ जो मुश्किल में साथ दें,\nऔर पार्टी के समय मोटू की तरह दिल खोलकर खादें।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "पार्टी"),
        shayariItem(1328, "फुरफुरी नगर की गलियों में आज भी रौनक़ छाई है,\nमोटू-पतलू की यारी ने हर दिल में जगह बनाई है।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "रौनक़"),
        shayariItem(1329, "हँसते रहो, मुस्कुराते रहो और खाते रहो गरम समोसे,\nइसी से ज़िंदगी चलती है और बनते हैं सुनहरे किस्से।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "किस्से"),
        shayariItem(1330, "मोटू-पतलू की तरह हर हाल में यारी निभाते रहो,\nगम चाहे जितने हों ज़िंदगी में, खुलकर मुस्कुराते रहो।", "फुरफुरी नगर स्पेशल", catMotuPatlu, "यारी")
    )
}
